const start = new Date('2026-10-01T00:00:00+02:00'); start.setHours(start.getHours()-1);
const now = new Date();
const res = await hass.callWS({type:'recorder/statistics_during_period', start_time: start.toISOString(), end_time: now.toISOString(), statistic_ids: ids, period:'hour', types:['sum','state']});
const out = {};
const monthStart = new Date('2026-10-01T00:00:00+02:00').getTime();
const lastFull = Math.floor(now.getTime()/3600000)*3600000;
for (const id of ids) {
  const rows = res[id] || [];
  const starts = new Set(rows.map(r => typeof r.start === 'number' ? r.start : Date.parse(r.start)));
  const missing = [];
  // hour h is covered by the reader if rows exist for h-1 and h (it differences consecutive rows)
  for (let t = monthStart; t < lastFull; t += 3600000) { if (!starts.has(t) || !starts.has(t-3600000)) missing.push(new Date(t).toLocaleString('pl-PL',{timeZone:'Europe/Warsaw'})); }
  const sumFirst = rows.length ? rows[0].sum : null, sumLast = rows.length ? rows[rows.length-1].sum : null;
  out[id] = {rows: rows.length, expected: (lastFull-monthStart)/3600000, missing_count: missing.length, missing_first: missing.slice(0,8), kwh_month: (sumLast!=null&&sumFirst!=null)? Math.round((sumLast-sumFirst)*10)/10 : null};
}
out

