  const kwh = new Map(); for (const r of (st[SID]||[])) kwh.set(typeof r.start==='number'?r.start:Date.parse(r.start), r.change||0);
  let over=0, overKwh=0, overExcess=0, maxP=0;
  for (let d=1; d<=days; d++) {
