        "description": "The seller caps the MONTHLY weighted-average energy price: at month end you pay min(cost, limit × kWh) per point of delivery — a settlement over the whole month, not an hourly cap. Each edition of the terms has its own validity, limit and basis; months no edition covers have no cap. Editions configured: {count}.",
        "data": {"action": "Action"},
    },
    "billing_terms": {
        "title": "PowerPilot – price cap edition",
        "description": "Dates must span whole months (from the 1st to the last day) and may not overlap another edition. Excise and distribution are always outside the cap. A net limit is grossed up with the VAT from the price settings.",
        "data": {
            "name": "Name (e.g. Tarcza Pstryk 2026)",
            "valid_from": "Valid from (first day of a month)",
            "valid_to": "Valid to (last day of a month)",
            "limit_kwh": "Limit of the monthly average (PLN/kWh)",
            "limit_includes_vat": "The limit includes VAT (gross) — off: the limit is net",
            "handling_fee_included": "The handling fee counts in the average (energy + handling fee) — off: energy only",
        },
    },
    "billing_meters": {
        "title": "PowerPilot – PPE 1 import meters",
        "description": "Meters (kWh) whose SUM is the grid import of PPE 1. Every load on that connection must be covered — an hour missing from any of them is unknown, never zero.",
        "data": {
            "ppe1_import_sensors": "PPE 1 grid-import meters (e.g. inverter AC-in to AC-out, AC-in to inverter, EV charger meter)",
        },
    },
}
PL = {
    "billing": {
        "title": "PowerPilot – Tarcza (limit ceny miesięcznej)",
        "description": "Sprzedawca ogranicza ŚREDNIĄ MIESIĘCZNĄ cenę energii: na koniec miesiąca płacisz min(koszt, limit × kWh) na każdym punkcie poboru — to rozliczenie całego miesiąca, nie limit godzinowy. Każda Tarcza ma własny okres, limit i sposób liczenia; miesiące bez Tarczy rozliczane są bez limitu. Skonfigurowane Tarcze: {count}.",
        "data": {"action": "Akcja"},
    },
    "billing_terms": {
        "title": "PowerPilot – Tarcza",
        "description": "Okres musi obejmować pełne miesiące (od 1. do ostatniego dnia) i nie może nachodzić na inną Tarczę. Akcyza i dystrybucja są zawsze poza Tarczą. Limit netto jest przeliczany na brutto stawką VAT z ustawień cen.",
        "data": {
            "name": "Nazwa (np. Tarcza Pstryk 2026)",
            "valid_from": "Obowiązuje od (1. dzień miesiąca)",
            "valid_to": "Obowiązuje do (ostatni dzień miesiąca)",
            "limit_kwh": "Limit średniej miesięcznej (PLN/kWh)",
            "limit_includes_vat": "Limit z VAT (brutto) — wyłączone: limit netto",
            "handling_fee_included": "Opłata za obsługę wlicza się do średniej (energia + obsługa) — wyłączone: tylko energia",
        },
    },
    "billing_meters": {
        "title": "PowerPilot – liczniki importu PPE 1",
        "description": "Liczniki (kWh), których SUMA to import z sieci na PPE 1. Muszą obejmować wszystkie odbiory tego przyłącza — godzina bez odczytu z któregokolwiek jest nieznana, nigdy zerowa.",
        "data": {
            "ppe1_import_sensors": "Liczniki importu PPE 1 (np. Victron AC-in do AC-out, AC-in do falownika, licznik ładowarki EV)",
        },
    },
}
ERR_EN = {
    "cap_terms_dates_order": "The start date is after the end date.",
    "cap_terms_whole_months": "The period must span whole months: from the 1st of a month to the last day of a month.",
    "cap_terms_limit": "The limit must be greater than zero.",
    "cap_terms_overlap": "This period overlaps another price cap edition.",
}
ERR_PL = {
    "cap_terms_dates_order": "Data początku jest późniejsza niż data końca.",
    "cap_terms_whole_months": "Okres musi obejmować pełne miesiące: od 1. dnia miesiąca do ostatniego dnia miesiąca.",
    "cap_terms_limit": "Limit musi być większy od zera.",
    "cap_terms_overlap": "Ten okres nachodzi na inną Tarczę.",
}
for name, steps, errors in (("strings.json", EN, ERR_EN), ("translations/en.json", EN, ERR_EN), ("translations/pl.json", PL, ERR_PL)):
    path = Path(name)
    data = json.loads(path.read_text(encoding="utf-8"))
    opts = data["options"]
    opts["step"].update(steps)
    opts.setdefault("error", {}).update(errors)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
EOF
